mapper.select:
SELECT id, order_no, user_id, land_id, amount, status,
       COALESCE(status_text, CASE status WHEN 1 THEN 'PAID' WHEN 2 THEN 'CANCELLED' ELSE 'PENDING_PAY' END) AS status_text,
       service_type, quantity, remark, pay_time, start_time, end_time,
       accept_time, complete_time, operator_id, operator_name, complete_images, complete_remark,
       create_time, update_time
FROM `order`


        user_id = #{userId}


        AND COALESCE(status_text, CASE status WHEN 1 THEN 'PAID' WHEN 2 THEN 'CANCELLED' ELSE 'PENDING_PAY' END) = #{status}


        AND service_type = #{serviceType}


        AND DATE(create_time) >= #{startDate}


        AND DATE(create_time) <= #{endDate}


ORDER BY id DESC

